select sum(total_diamonds) countTotal
from ${dbLive}.live_video_prop


		and p_user_id = #{pUserId}


		and to_user_id =#{toUserId}


		and FROM_UNIXTIME(create_time) >= #{startTime}
		and FROM_UNIXTIME(create_time) <= #{endTime}

SELECT p_user_id as pUserId, p_user_name as pUserName, to_user_id as toUserId, SUM( total_diamonds ) as totalDiamonds FROM ${dbLive}.live_video_prop
and to_user_id NOT IN ( '0', '-1' ) and p_user_id IN ( SELECT id FROM ${dbMain}.member_info WHERE status in ('2','0'))
and to_user_id =#{toUserId}
and create_date = #{testAccountCreateTime}
GROUP BY p_user_id, to_user_id ORDER BY to_user_id

SELECT SUM( total_diamonds ) as testAccountPorpTotal FROM ${dbLive}.live_video_prop
and to_user_id NOT IN ( '0', '-1' ) and p_user_id IN ( SELECT id FROM ${dbMain}.member_info WHERE STATUS = '2' )
and to_user_id =#{toUserId}
and create_date = #{testAccountCreateTime}
